--
-- Table structure for table `chat_sessions`
--

DROP TABLE IF EXISTS `chat_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `chat_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `customer_id` bigint(20) unsigned DEFAULT NULL,
  `guest_name` varchar(255) DEFAULT NULL,
  `guest_phone` varchar(255) DEFAULT NULL,
  `guest_token` varchar(255) DEFAULT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `channel` varchar(255) NOT NULL DEFAULT 'web',
  `status` enum('bot','queued','active','closed','resolved') NOT NULL DEFAULT 'bot',
  `inquiry_type` enum('cs','purchase','complaint') NOT NULL DEFAULT 'cs',
  `priority` enum('low','normal','high','urgent') NOT NULL DEFAULT 'normal',
  `rating` int(11) DEFAULT NULL,
  `close_reason` text DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `first_response_at` timestamp NULL DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `visitor_left` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `chat_sessions_uuid_unique` (`uuid`),
  UNIQUE KEY `chat_sessions_guest_token_unique` (`guest_token`),
  KEY `chat_sessions_status_created_at_index` (`status`,`created_at`),
  KEY `chat_sessions_customer_id_status_index` (`customer_id`,`status`),
