INSERT INTO `faqs` VALUES (1,'Berapa lama pesanan saya diproses?','<p>⁠Pesanan akan kami proses secepat mungkin selama masih dalam jam operasional, yaitu 10.00 - 20.00 WIB. Jika pesanan dilakukan di luar jam operasional, pesanan akan kami proses pada hari kerja berikutnya.</p>','Umum',0,1,6,18,'2026-05-26 13:25:14','2026-09-02 04:32:01',NULL),(2,'Apakah bisa untuk mengambil pesanan di cabang terdekat?','<p>Tentu, bisa! Saat melakukan checkout, pilih opsi “Ambil di Tempat”, kemudian kamu dapat mengambil pesanan langsung di cabang TB Store yang tersedia sesuai pilihanmu.</p>','Umum',1,1,6,18,'2026-05-26 18:45:41','2026-09-02 04:32:38',NULL),(3,'Bagaimana cara claim garansi device pod/mod?','<p>Segera hadir</p>','Umum',2,1,6,6,'2026-05-26 18:46:58','2026-07-09 07:19:20',NULL);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
