DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `alternative_name` varchar(255) DEFAULT NULL,
  `classification_id` bigint(20) unsigned DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `collections` varchar(255) DEFAULT NULL,
  `brand` varchar(255) DEFAULT NULL,
  `condition_id` varchar(255) NOT NULL DEFAULT 'N',
  `sku` varchar(255) DEFAULT NULL,
  `barcode` varchar(255) DEFAULT NULL,
  `buy_price` decimal(15,2) DEFAULT NULL,
  `market_price` decimal(15,2) DEFAULT NULL,
  `sell_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `pos_sell_price` decimal(15,2) DEFAULT NULL,
  `pos_sell_price_dynamic` tinyint(4) NOT NULL DEFAULT 0,
  `comission` decimal(15,2) NOT NULL DEFAULT 0.00,
  `track_inventory` tinyint(4) NOT NULL DEFAULT 1,
  `stock_qty` int(10) unsigned NOT NULL DEFAULT 0,
  `uom` varchar(255) DEFAULT NULL,
  `weight_kg` decimal(10,3) DEFAULT NULL,
  `loyalty_points` int(11) NOT NULL DEFAULT 0,
  `published` tinyint(4) NOT NULL DEFAULT 1,
  `pos_hidden` tinyint(4) NOT NULL DEFAULT 0,
  `description` text DEFAULT NULL,
  `photo_1` text DEFAULT NULL,
  `photo_2` text DEFAULT NULL,
  `photo_3` text DEFAULT NULL,
  `photo_4` text DEFAULT NULL,
  `photo_5` text DEFAULT NULL,
  `photo_6` text DEFAULT NULL,
  `photo_7` text DEFAULT NULL,
  `photo_8` text DEFAULT NULL,
  `photo_9` text DEFAULT NULL,
  `photo_10` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `tax_free_item` varchar(255) NOT NULL DEFAULT 'No',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `products_name_index` (`name`),
  KEY `products_category_index` (`category`),
  KEY `products_sku_index` (`sku`),
  KEY `products_published_index` (`published`)
) ENGINE=InnoDB AUTO_INCREMENT=1437 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

